fn default_options() -> CompressOptions {
    CompressOptions {
        drop_debugger: false,
        unused: CompressOptionsUnused::Keep,
        ..CompressOptions::smallest()
    }
}

fn run(source: &str, opts: CompressOptions) -> String {
    let allocator = Allocator::default();
    let ret = Parser::new(&allocator, source, SourceType::mjs()).parse();
    let mut program = ret.program;
    Compressor::new(&allocator).build(&mut program, opts);
    Codegen::new()
        .with_options(CodegenOptions { single_quote: true, ..Default::default() })
        .build(&program)
        .code
}

fn show(label: &str, source: &str, keep_names: bool) {
    let mut opts = default_options();
    if keep_names {
