+impl<'a> MayHaveSideEffects<'a> for ObjectProperty<'a> {
+    fn may_have_side_effects(&self, ctx: &impl MayHaveSideEffectsContext<'a>) -> bool {
+        self.key.may_have_side_effects(ctx) || self.value.may_have_side_effects(ctx)
+    }
+}
